import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        // Validate format parameter
        if (format == null || (!format.equals("json") && !format.equals("csv"))) {
            format = "json";
        }

        // Audit logging for compliance
        log.info(String.format("Report request: type=%s, range=%s, dept=%s, user=%s",
            reportType, dateRange, department, req.getRemoteUser()));

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query based on report type
            String query;
            if ("summary".equals(reportType)) {
                query = "SELECT department, COUNT(*) as cnt, SUM(amount) as total " +
                        "FROM transactions WHERE department = '" + department + "' " +
                        "AND created_at BETWEEN '" + dateRange + "' " +
                        "GROUP BY department ORDER BY total DESC";
            } else if ("detail".equals(reportType)) {
                query = "SELECT id, employee_name, amount, description, created_at " +
                        "FROM transactions WHERE department = '" + department + "' " +
                        "AND created_at >= '" + dateRange + "' " +
                        "ORDER BY created_at DESC LIMIT 500";
            } else {
                query = "SELECT department, COUNT(*) as cnt FROM transactions " +
                        "WHERE department = '" + department + "' GROUP BY department";
            }

            rs = stmt.executeQuery(query);

            resp.setContentType(format.equals("csv") ? "text/csv" : "application/json");
            PrintWriter out = resp.getWriter();

            if (format.equals("csv")) {
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                for (int i = 1; i <= cols; i++) {
                    out.print(meta.getColumnName(i));
                    if (i < cols) out.print(",");
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        out.print(rs.getString(i));
                        if (i < cols) out.print(",");
                    }
                    out.println();
                }
            } else {
                out.print("[\n");
                ResultSetMetaData meta = rs.getMetaData();
                int cols = meta.getColumnCount();
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.print("  {");
                    for (int i = 1; i <= cols; i++) {
                        out.print("\"" + meta.getColumnName(i) + "\":");
                        out.print("\"" + rs.getString(i) + "\"");
                        if (i < cols) out.print(",");
                    }
                    out.print("}");
                    first = false;
                }
                out.print("\n]");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }
}
